import{_ as e,c as o,o as t,a2 as a}from"./chunks/framework.DdOM6S6U.js";const f=JSON.parse('{"title":"ADR: Form events (ext → formEvents)","description":"","frontmatter":{"sidebarPos":16,"sidebarTitle":"ADR — Form events"},"headers":[],"relativePath":"system-reference/adr-form-events.md","filePath":"system-reference/adr-form-events.md","lastUpdated":1787876309000}'),r={name:"system-reference/adr-form-events.md"},c=a('<h1 id="adr-form-events-ext-→-formevents" tabindex="-1">ADR: Form events (<code>ext</code> → <code>formEvents</code>) <a class="header-anchor" href="#adr-form-events-ext-→-formevents" aria-label="Permalink to &quot;ADR: Form events (`ext` → `formEvents`)&quot;">​</a></h1><p><strong>Status:</strong> Accepted, incremental<br><strong>Date:</strong> 2026-08-28</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Admin inputs declared cross-field behaviour with <strong><code>ext</code></strong>. Two PHP compilers (trait vs helper) drifted. Vue <code>handleEvents</code> dispatched <code>formEventFormatters</code> from schema <strong><code>event</code></strong>.</p><p>Problems:</p><ol><li><strong><code>ext</code> is overloaded.</strong> Event DSL (<code>set</code>, <code>update</code>, <code>lock</code>, …) shares the key with type aliases (<code>date</code>, <code>time</code>, <code>price</code>, <code>scroll</code>, <code>number</code>, <code>relationship</code>, <code>morphTo</code>).</li><li><strong>Two PHP compilers</strong> disagreed (<code>set</code> used undefined <code>$targetPropName</code> in the helper).</li><li><strong>Two JS paths:</strong> <code>handleEvents</code> + formatters vs legacy <code>handleInputEvents</code> switch (permalink/lock).</li><li><strong>Translated vs scalar.</strong> <code>set</code>/<code>update</code> with <code>modelValue</code> copied locale maps onto string fields (issue #51).</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="canonical-config-key-formevents" tabindex="-1">Canonical config key: <code>formEvents</code> <a class="header-anchor" href="#canonical-config-key-formevents" aria-label="Permalink to &quot;Canonical config key: `formEvents`&quot;">​</a></h3><p>Input config uses <strong><code>formEvents</code></strong> (pipe string or nested arrays, same shapes as the old <code>ext</code> DSL).</p><h3 id="ext-fallback-until-v14" tabindex="-1"><code>ext</code> fallback until v14 <a class="header-anchor" href="#ext-fallback-until-v14" aria-label="Permalink to &quot;`ext` fallback until v14&quot;">​</a></h3><p>If <strong><code>formEvents</code> is absent</strong>, compile event DSL from <strong><code>ext</code></strong>. When both are present, <strong><code>formEvents</code> wins</strong>. Compiling from <code>ext</code> emits a <strong>v13</strong> deprecation (<code>unusualify/modularous</code> 13.0). <strong>v14 removes <code>ext</code> as an event source.</strong></p><h3 id="type-aliases-stay-out-of-the-compiler" tabindex="-1">Type aliases stay out of the compiler <a class="header-anchor" href="#type-aliases-stay-out-of-the-compiler" aria-label="Permalink to &quot;Type aliases stay out of the compiler&quot;">​</a></h3><p><code>date</code> | <code>time</code> | <code>price</code> | <code>softCurrency</code> | <code>scroll</code> | <code>number</code> | <code>relationship</code> | <code>morphTo</code> are <strong>not</strong> form events. They must be migrated to <code>type</code> / hydrate options <strong>before</strong> v14 deletes <code>ext</code>.</p><h3 id="runtime-schema" tabindex="-1">Runtime schema <a class="header-anchor" href="#runtime-schema" aria-label="Permalink to &quot;Runtime schema&quot;">​</a></h3><p><code>FormEventCompiler</code> dual-writes schema <strong><code>formEvents[]</code></strong> (compiled <code>formatXxx:args</code> tokens) and legacy <strong><code>event</code></strong> (pipe). Vue <code>resolveFormEventTokens</code> reads <code>formEvents</code> first, then <code>event</code>.</p><h3 id="compiler" tabindex="-1">Compiler <a class="header-anchor" href="#compiler" aria-label="Permalink to &quot;Compiler&quot;">​</a></h3><p>One PHP <code>FormEventCompiler</code> (<code>src/Hydrates/FormEventCompiler.php</code>). <code>FormSchema::hydrateInputExtension</code> and <code>hydrate_input_extension()</code> call it.</p><h3 id="later-v14" tabindex="-1">Later (v14) <a class="header-anchor" href="#later-v14" aria-label="Permalink to &quot;Later (v14)&quot;">​</a></h3><ol><li>Remove <code>ext</code> event fallback.</li><li>Drop <code>ext</code> entirely after type aliases have a home.</li><li>Optionally retire <code>handleInputEvents</code> (legacy permalink/lock); formatters remain the runtime path.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New module / package inputs write <strong><code>formEvents</code></strong>. Host apps may keep <code>ext</code> until they migrate; they will see the v13 warning.</li><li>Do not migrate <code>b2press-app</code> from this package repo.</li><li>Issue #51 coerce stays independent of the v14 cut.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Guide: <a href="/guide/js/form-events">Form events</a></li><li><code>src/Hydrates/FormEventCompiler.php</code></li><li><code>vue/src/js/utils/formEvents.js</code>, <code>resolveFormEventTokens.js</code>, <code>formEventFormatters/</code></li></ul>',23),s=[c];function d(n,i,l,m,h,p){return t(),o("div",null,s)}const v=e(r,[["render",d]]);export{f as __pageData,v as default};
